<?php require_once __DIR__.'/../_bootstrap.php'; $d=body(); required($d,['phone','password']); $s=db()->prepare('SELECT * FROM users WHERE phone=?');$s->execute([$d['phone']]);$u=$s->fetch(); if(!$u||!password_verify($d['password'],$u['password'])) fail('Invalid phone or password',401); if($u['status']!=='active') fail('Account is suspended',403); unset($u['password']);$token=jwt_encode(['id'=>(int)$u['id'],'role'=>$u['role'],'exp'=>time()+604800]);out(['success'=>true,'token'=>$token,'user'=>$u]);
